<?php require '../includes/db.php';require '../includes/functions.php';$id=(int)($_POST['book_id']??0);$qty=max(1,(int)($_POST['quantity']??1));$s=$conn->prepare('SELECT stock FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();$b=$s->get_result()->fetch_assoc();if($b&&$b['stock']>0){$_SESSION['cart'][$id]=min((int)$b['stock'],(int)($_SESSION['cart'][$id]??0)+$qty);}header('Location: /PHP_Online_Bookstore_21_Practicals/cart/');exit;?>
